mapper.select:
SELECT b.* FROM (SELECT ROWNUM AS num, A.* FROM (SELECT COUNT(*) OVER() AS task_counts, m.title, u.user_name, m.created_at, c.code_name AS type_name, m.attachment_group_id, m.meeting_log_id FROM meeting_logs m JOIN projects p ON m.project_id = p.project_id JOIN users u ON m.created_by = u.user_id LEFT JOIN common_code c ON m.meeting_type_code = c.code_value WHERE (p.project_id=#{projectId} OR p.parent_project_id = #{projectId})
AND m.created_by = #{createdBy}
AND m.meeting_type_code = #{meetingTypeCode}
AND m.created_at >= #{startDate}
AND m.created_at <= #{endDate}
AND m.title LIKE '%' || #{search} || '%'
ORDER BY m.created_at DESC) A WHERE ROWNUM BETWEEN 1 AND #{endNum})b WHERE b.num >= #{startNum}
